import {firebaseConfig,region,appCheckSiteKey} from './config.js';
import {renderOverview,renderHistory,renderSellers} from './render.js';
const $=id=>document.getElementById(id);
let auth,authApi,api,overview,rows=[],cursor=null,kind='sales',generation=0,historyGeneration=0;
function notice(text,error=false){$('notice').textContent=text;$('notice').classList.toggle('error',error);}
function errorMessage(error){return error.code==='functions/permission-denied'?'Esta cuenta no está autorizada. Entra con la cuenta del dueño.':error.code==='auth/popup-blocked'?'Permite la ventana de acceso de Google e intenta de nuevo.':error.code==='auth/operation-not-allowed'?'El acceso con Google está pendiente de activación.':error.code==='auth/popup-closed-by-user'?'Se cerró la ventana de acceso.':'No se pudo completar la consulta. Revisa la conexión e intenta de nuevo.';}
function clearPrivate(){generation++;historyGeneration++;overview=undefined;rows=[];cursor=null;$('dashboard').hidden=true;$('history-rows').replaceChildren();$('seller-rows').replaceChildren();$('detail-dialog').close();$('detail-fields').replaceChildren();}
async function loadOverview(){const stamp=++generation;try{const {data}=await api('ownerOverview')({month:$('month').value||undefined});if(stamp!==generation||!auth.currentUser)return;overview=data;$('month').value=data.month;$('month').max=data.today.slice(0,7);if(!$('seller-day').value||!data.days.some(r=>r.day===$('seller-day').value))$('seller-day').value=data.month===data.today.slice(0,7)?data.today:data.monthDays[0];$('seller-day').max=data.today;renderOverview(data,$('currency').value);$('dashboard').hidden=false;$('login-panel').hidden=true;notice('Actualizado. Las cotizaciones y las ventas se muestran por separado.');}catch(error){if(stamp!==generation)return;if(error.code==='functions/permission-denied'){clearPrivate();$('login-panel').hidden=false;}notice(errorMessage(error),true);}}
async function loadHistory(reset=true){const stamp=++historyGeneration,from=$('from').value,to=$('to').value;if(from&&to&&from>to){$('history-state').textContent='La fecha inicial debe ser anterior a la final.';return;}$('more').disabled=true;$('history-state').textContent='Cargando registros…';try{const {data}=await api('ownerHistory')({kind,from,to,cursor:reset?null:cursor});if(stamp!==historyGeneration||!auth.currentUser)return;rows=reset?data.rows:[...rows,...data.rows];cursor=data.next;renderHistory(rows,$('currency').value);$('more').hidden=!cursor;$('history-state').textContent=`${rows.length} registros cargados${cursor?' · Hay más registros':''}.`;}catch(error){if(stamp===historyGeneration)$('history-state').textContent=errorMessage(error);}finally{if(stamp===historyGeneration)$('more').disabled=false;}}
$('login').addEventListener('click',async()=>{try{const provider=new authApi.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});await authApi.signInWithPopup(auth,provider);}catch(error){notice(errorMessage(error),true);}});
$('logout').addEventListener('click',async()=>{clearPrivate();await authApi.signOut(auth);});
$('refresh').addEventListener('click',async()=>{await loadOverview();if(overview)await loadHistory();});
$('month').addEventListener('change',()=>loadOverview());
$('currency').addEventListener('change',()=>{if(overview)renderOverview(overview,$('currency').value);renderHistory(rows,$('currency').value);});
$('seller-day').addEventListener('change',async()=>{const day=$('seller-day').value;if(!day||!overview)return;if(!overview.days.some(r=>r.day===day)){$('month').value=day.slice(0,7);await loadOverview();}else renderSellers(overview,$('currency').value,day);});
for(const [id,value]of [['sales-tab','sales'],['calculations-tab','calculations']])$(id).addEventListener('click',()=>{kind=value;for(const button of ['sales-tab','calculations-tab']){$(button).classList.toggle('selected',button===id);$(button).setAttribute('aria-pressed',String(button===id));}loadHistory();});
$('history-filters').addEventListener('submit',e=>{e.preventDefault();loadHistory();});$('clear-filters').addEventListener('click',()=>{$('from').value='';$('to').value='';loadHistory();});$('more').addEventListener('click',()=>loadHistory(false));
async function start(){try{const base='https://www.gstatic.com/firebasejs/12.19.0/';const [app,authentication,functions,check]=await Promise.all([import(base+'firebase-app.js'),import(base+'firebase-auth.js'),import(base+'firebase-functions.js'),import(base+'firebase-app-check.js')]);const firebase=app.initializeApp(firebaseConfig,'pitstop-owner');check.initializeAppCheck(firebase,{provider:new check.ReCaptchaEnterpriseProvider(appCheckSiteKey),isTokenAutoRefreshEnabled:true});authApi=authentication;auth=authentication.getAuth(firebase);await authentication.setPersistence(auth,authentication.browserSessionPersistence);api=name=>functions.httpsCallable(functions.getFunctions(firebase,region),name);$('login').disabled=false;authentication.onAuthStateChanged(auth,async user=>{clearPrivate();$('logout').hidden=!user;$('account').textContent=user?.email||'';if(!user){$('login-panel').hidden=false;notice('Inicia sesión con la cuenta autorizada.');return;}notice('Validando acceso…');await loadOverview();if(overview)await loadHistory();});}catch(error){notice(errorMessage(error),true);}}
start();
